begin;
create function pg_temp.expect(ok boolean,label text)returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'MERGE SEARCH TEST: %',label;end if;end$$;
create function pg_temp.failed(q text)returns boolean language plpgsql as $$begin execute q;return false;exception when others then return true;end$$;
create function pg_temp.reject_archive()returns trigger language plpgsql as $$begin if new.deleted_at is not null then raise exception 'synthetic merge failure';end if;return new;end$$;
create function pg_temp.denied(q text)returns boolean language plpgsql as $$begin execute q;return false;exception when insufficient_privilege then return true;end$$;
insert into public.app_members(email) values('merge.admin@example.com'),('merge.other@example.com'),('merge.docs@example.com');
insert into public.member_permissions(email,permission) values('merge.admin@example.com','admin'),('merge.admin@example.com','documents'),('merge.admin@example.com','portfolio'),('merge.docs@example.com','documents');
insert into public.companies(id,name) values('aa000000-0000-0000-0000-000000000001','Retained fixture'),('aa000000-0000-0000-0000-000000000002','Dropped fixture');
insert into public.company_aliases(company_id,alias) values('aa000000-0000-0000-0000-000000000002','Origin alias');
insert into public.company_domains(company_id,domain) values('aa000000-0000-0000-0000-000000000002','merge-fixture.example.com');
insert into public.deals(id,company_id,name,notes,restricted,stage_id) values('aa000000-0000-0000-0000-000000000003','aa000000-0000-0000-0000-000000000002','Secretneedle round','Secretneedle evidence',true,(select id from public.pipeline_stages order by sort_order limit 1));
insert into public.deal_access_members(deal_id,member_email,access_role) values('aa000000-0000-0000-0000-000000000003','merge.docs@example.com','viewer');
insert into public.people(id,name,primary_organization_id) values('aa000000-0000-0000-0000-000000000004','Linked fixture','aa000000-0000-0000-0000-000000000002');
insert into public.documents(id,company_id,deal_id,name,source,drive_file_id,uploaded_by) values('aa000000-0000-0000-0000-000000000005','aa000000-0000-0000-0000-000000000002','aa000000-0000-0000-0000-000000000003','Secretneedle document','drive_link','merge-doc','merge.admin@example.com');
insert into public.interactions(id,company_id,deal_id,type,subject,occurred_at) values('aa000000-0000-0000-0000-000000000006','aa000000-0000-0000-0000-000000000002','aa000000-0000-0000-0000-000000000003','note','Secretneedle note',now());
insert into public.tasks(id,company_id,deal_id,title) values('aa000000-0000-0000-0000-000000000007','aa000000-0000-0000-0000-000000000002','aa000000-0000-0000-0000-000000000003','Secretneedle task');
insert into public.investments(id,external_ref,company_id,deal_id) values('aa000000-0000-0000-0000-000000000008','merge-test-investment','aa000000-0000-0000-0000-000000000002','aa000000-0000-0000-0000-000000000003');
insert into public.investors(id,display_name) values('aa000000-0000-0000-0000-000000000009','Investorpositionneedle');
insert into public.investor_positions(investment_id,investor_id,amount,notes) values('aa000000-0000-0000-0000-000000000008','aa000000-0000-0000-0000-000000000009',100000,'Investorpositionneedle');
create temp table ids(k text primary key,v uuid);grant all on ids to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","email":"merge.other@example.com"}',true);
select pg_temp.expect(pg_temp.denied($q$select public.merge_companies('aa000000-0000-0000-0000-000000000001','aa000000-0000-0000-0000-000000000002')$q$),'non-Admin cannot merge restricted company');
select pg_temp.expect(not exists(select 1 from public.search_workspace('Secretneedle')),'search hides all restricted descendants');
select set_config('request.jwt.claims','{"role":"authenticated","email":"merge.admin@example.com"}',true);
insert into ids values('comment',public.comment_post_visible(null,'aa000000-0000-0000-0000-000000000002','aa000000-0000-0000-0000-000000000003',null,'page','Fixture',null,'Private fixture',array[]::text[],array['merge.docs@example.com']));
insert into ids values('board',public.crm_create_flexible_board('Merge fixture',false));
insert into public.crm_board_columns(board_id,name,sort_order) values((select v from ids where k='board'),'To do',0);
insert into ids select 'column',id from public.crm_board_columns where board_id=(select v from ids where k='board');
select public.import_directory_to_board((select v from ids where k='board'),(select v from ids where k='column'),'company',array['aa000000-0000-0000-0000-000000000001','aa000000-0000-0000-0000-000000000002']::uuid[],false);
insert into ids values('lp',public.lp_ensure_board());
insert into ids select 'lpcolumn',id from public.lp_board_columns where board_id=(select v from ids where k='lp') order by sort_order limit 1;
select public.import_directory_to_board((select v from ids where k='lp'),(select v from ids where k='lpcolumn'),'company',array['aa000000-0000-0000-0000-000000000001','aa000000-0000-0000-0000-000000000002']::uuid[],true);
reset role;
create trigger fail_merge before update on public.companies for each row execute function pg_temp.reject_archive();
set local role authenticated;
select pg_temp.expect(pg_temp.failed($q$select public.merge_companies('aa000000-0000-0000-0000-000000000001','aa000000-0000-0000-0000-000000000002')$q$),'forced failure aborts merge');
select pg_temp.expect((select company_id from public.deals where id='aa000000-0000-0000-0000-000000000003')='aa000000-0000-0000-0000-000000000002' and (select count(*) from public.crm_board_items where source_company_id='aa000000-0000-0000-0000-000000000002')=1 and not exists(select 1 from public.audit_log where entity_table='companies' and entity_id='aa000000-0000-0000-0000-000000000002' and after_row->>'merged_into_id'='aa000000-0000-0000-0000-000000000001'),'all moved links and audits roll back together');
reset role;drop trigger fail_merge on public.companies;
set local role authenticated;
select public.merge_companies('aa000000-0000-0000-0000-000000000001','aa000000-0000-0000-0000-000000000002');
select pg_temp.expect((select count(*) from public.crm_board_items where board_id=(select v from ids where k='board') and source_company_id='aa000000-0000-0000-0000-000000000001')=2,'both board cards retain live company link');
select pg_temp.expect((select count(*) from public.lp_board_cards where board_id=(select v from ids where k='lp') and source_company_id='aa000000-0000-0000-0000-000000000001')=2,'both LP cards retain live company link');
select pg_temp.expect((select count(*) from public.crm_board_items where merged_source_company_id='aa000000-0000-0000-0000-000000000002')=1,'original card identity retained');
select pg_temp.expect(public.import_directory_to_board((select v from ids where k='board'),(select v from ids where k='column'),'company',array['aa000000-0000-0000-0000-000000000001']::uuid[],false)=0,'reimport remains idempotent after merge');
select pg_temp.expect((select company_id from public.deals where id='aa000000-0000-0000-0000-000000000003')='aa000000-0000-0000-0000-000000000001','round reassigned');
select pg_temp.expect((select company_id from public.documents where id='aa000000-0000-0000-0000-000000000005')='aa000000-0000-0000-0000-000000000001' and (select company_id from public.tasks where id='aa000000-0000-0000-0000-000000000007')='aa000000-0000-0000-0000-000000000001' and (select company_id from public.record_comments where id=(select v from ids where k='comment'))='aa000000-0000-0000-0000-000000000001','documents tasks comments reassigned');
select pg_temp.expect((select company_id from public.investments where id='aa000000-0000-0000-0000-000000000008')='aa000000-0000-0000-0000-000000000001' and exists(select 1 from public.investor_positions where investment_id='aa000000-0000-0000-0000-000000000008' and amount=100000),'investment reassigned without changing investor positions');
select pg_temp.expect(not exists(select 1 from public.search_workspace('Investorpositionneedle')),'actual investor/position fixture cannot enter search');
select pg_temp.expect((select primary_organization_id from public.people where id='aa000000-0000-0000-0000-000000000004')='aa000000-0000-0000-0000-000000000001','People reassigned');
select pg_temp.expect((select restricted from public.deals where id='aa000000-0000-0000-0000-000000000003') and exists(select 1 from public.deal_access_members where deal_id='aa000000-0000-0000-0000-000000000003' and member_email='merge.docs@example.com' and access_role='viewer'),'Deal restriction and ACL preserved');
select pg_temp.expect(exists(select 1 from public.audit_log where entity_table='companies' and entity_id='aa000000-0000-0000-0000-000000000002' and after_row->>'merged_into_id'='aa000000-0000-0000-0000-000000000001'),'merge audited');
select set_config('request.jwt.claims','{"role":"authenticated","email":"merge.other@example.com"}',true);
select pg_temp.expect(not exists(select 1 from public.search_workspace('Secretneedle')),'merge does not expose restricted descendants');
select set_config('request.jwt.claims','{"role":"authenticated","email":"merge.docs@example.com"}',true);
select pg_temp.expect(exists(select 1 from public.search_workspace('Secretneedle') where kind='document'),'authorized Documents viewer can search round evidence');
reset role;
-- Investor-private documents are excluded even for an Admin with both areas.
insert into public.documents(company_id,name,source,drive_file_id,entity_role) values('aa000000-0000-0000-0000-000000000001','Investorprivateneedle','drive_link','investor-private','LP');
insert into public.documents(company_id,name,source,drive_file_id,entity_role) values('aa000000-0000-0000-0000-000000000001','Portfolioneedle','drive_link','portfolio-private','SPV');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","email":"merge.docs@example.com"}',true);
select pg_temp.expect(not exists(select 1 from public.search_workspace('Portfolioneedle')),'Documents alone cannot search Portfolio files');
select set_config('request.jwt.claims','{"role":"authenticated","email":"merge.admin@example.com"}',true);
select pg_temp.expect(not exists(select 1 from public.search_workspace('Investorprivateneedle')),'investor-private file excluded even for Admin');
select pg_temp.expect(not exists(select 1 from public.search_workspace('Secretneedle') where kind in ('investor','position','investor_position')),'no investor positions search category');
reset role;
-- Assert that no actual company_id FK child still points at the archive.
do $$declare r record;v_count bigint;begin
  for r in select distinct t.relname table_name from pg_constraint fk join pg_class t on t.oid=fk.conrelid join pg_namespace n on n.oid=t.relnamespace join pg_attribute a on a.attrelid=t.oid and a.attnum=any(fk.conkey) where fk.contype='f' and fk.confrelid='public.companies'::regclass and n.nspname='public' and a.attname='company_id' loop
    execute format('select count(*) from public.%I where company_id=$1',r.table_name) into v_count using 'aa000000-0000-0000-0000-000000000002'::uuid;
    perform pg_temp.expect(v_count=0,'all foreign-key children moved: '||r.table_name);
  end loop;
end$$;
-- Selective search volume: representative 20k companies, not enable_seqscan=off.
insert into public.companies(name,description) select 'Volume fixture '||g,case when g=9999 then 'selectiveneedle' else 'ordinary fixture' end from generate_series(1,20000)g;
-- Flush GIN pending lists as normal vacuum maintenance would after bulk load.
select gin_clean_pending_list('public.companies_search_idx'::regclass);
select gin_clean_pending_list('public.companies_name_trgm'::regclass);
analyze public.companies;
do $$declare plan json;begin
  execute $q$explain(format json) select id from public.companies where deleted_at is null and to_tsvector('simple',coalesce(name,'')||' '||coalesce(description,''))@@websearch_to_tsquery('simple','selectiveneedle') union select id from public.companies where deleted_at is null and name OPERATOR(public.%) 'selectiveneedle' union select id from public.companies where deleted_at is null and name ilike '%selectiveneedle%' $q$ into plan;
  perform pg_temp.expect(plan::text like '%companies_search_idx%' and plan::text like '%companies_name_trgm%','realistic selective predicate uses GIN/Bitmap indexes: '||plan::text);
end$$;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","email":"merge.other@example.com"}',true);
select pg_temp.expect((select count(*) from public.search_workspace('Volume'))=30,'bounded to 30 results');
select pg_temp.expect((select count(*) from public.search_workspace('selectiveneedle'))=1,'full-text indexed content searchable');
select pg_temp.expect(not exists(select 1 from public.search_workspace('x')),'short queries rejected');
reset role;
rollback;
